import XCTest
@testable import LKCore
import LKStrings
import LKDesign

/// Parity gate: the Swift ports must reproduce the web JS reference exactly (vectors generated by scripts/native/gen.mjs).
final class ConformanceTests: XCTestCase {
    struct Vectors: Decodable {
        struct Params: Decodable { let W: [Double]; let DECAY: Double; let FACTOR: Double; let MAX_IVL: Int; let retentionTarget: Double; let dayRolloverHour: Int }
        struct Step: Decodable { let grade: Int; let now: Int64; let S: Double; let D: Double; let reps: Int; let lapses: Int; let step: Int; let interval: Int; let due: Int64 }
        struct Seq: Decodable { let start: Int64; let grades: [Int]; let steps: [Step] }
        struct Norm: Decodable { let `in`: String; let out: String }
        struct Check: Decodable { struct It: Decodable { let type: String; let answer: String; let choice: Bool? }; let item: It; let ans: AnyAns; let ok: Bool }
        struct Ans: Decodable { let norm: [Norm]; let check: [Check] }
        let params: Params; let fsrs: [Seq]; let answer: Ans
    }
    enum AnyAns: Decodable {
        case s(String), n(Double), b(Bool), a([String])
        init(from d: Decoder) throws {
            let c = try d.singleValueContainer()
            if let v = try? c.decode(Bool.self) { self = .b(v) } else if let v = try? c.decode(Double.self) { self = .n(v) }
            else if let v = try? c.decode([String].self) { self = .a(v) } else { self = .s(try c.decode(String.self)) }
        }
        var given: Answer.Given { switch self { case .s(let s): .text(s); case .n(let n): .score(n); case .b(let b): .matched(b); case .a(let a): .words(a) } }
    }
    lazy var v: Vectors = {
        let url = Bundle.module.url(forResource: "scoring", withExtension: "json")!
        return try! JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }()

    func testParamsMatchWebSource() {
        let p = SRSParams.fsrs5
        XCTAssertEqual(p.W, v.params.W); XCTAssertEqual(p.DECAY, v.params.DECAY); XCTAssertEqual(p.FACTOR, v.params.FACTOR, accuracy: 1e-15)
        XCTAssertEqual(p.MAX_IVL, v.params.MAX_IVL); XCTAssertEqual(p.retentionTarget, v.params.retentionTarget); XCTAssertEqual(p.dayRolloverHour, v.params.dayRolloverHour)
    }

    func testFSRSMatchesWeb() {
        var cal = Calendar(identifier: .gregorian); cal.timeZone = TimeZone(identifier: "UTC")!
        let srs = SRS(calendar: cal)
        for (si, seq) in v.fsrs.enumerated() {
            var c = SRSCard(due: seq.start)
            for (i, st) in seq.steps.enumerated() {
                c = srs.review(c, grade: st.grade, now: st.now)
                let at = "seq \(si) step \(i)"
                XCTAssertEqual(c.S!, st.S, accuracy: 1e-9, at); XCTAssertEqual(c.D!, st.D, accuracy: 1e-9, at)
                XCTAssertEqual(c.reps, st.reps, at); XCTAssertEqual(c.lapses, st.lapses, at); XCTAssertEqual(c.step, st.step, at)
                XCTAssertEqual(c.interval, st.interval, at); XCTAssertEqual(c.due, st.due, at)
            }
        }
    }

    func testAnswerNormMatchesWeb() { for n in v.answer.norm { XCTAssertEqual(Answer.norm(n.in), n.out, "norm(\(n.in))") } }

    func testAnswerCheckMatchesWeb() {
        for c in v.answer.check {
            let it = Answer.Item(type: c.item.type, answer: c.item.answer, choice: c.item.choice ?? false)
            XCTAssertEqual(Answer.check(it, c.ans.given), c.ok, "\(c.item.type) \(c.ans)")
        }
    }

    func testEveryKeyInAll15Languages() {
        XCTAssertEqual(L10nLangs.all.count, 15)
        for l in L10nLangs.all { let t = L10n(lang: l); for k in L10nKey.allCases { XCTAssertTrue(t.has(k), "\(l): \(k.rawValue)") } }
    }

    func testFrameIsFiveTabs() {
        XCTAssertEqual(LKFrame.shared.tabs.map(\.k), ["home", "vocab", "skills", "tests", "me"])
        XCTAssertEqual(LKFrame.shared.width, 390); XCTAssertGreaterThanOrEqual(LKFrame.shared.minTap, 44)
    }
}
